package glitch

import data.glitch_lib

# Insecure protocol values indicating lack of integrity checks
insecure_protocols := {"http", "tcp", "udp", "plaintext", "ftp", "telnet"}

# Security-related attribute names for integrity/encryption checks
ssl_tls_attrs := {"ssl", "tls", "verify_ssl", "verify_tls", "insecure_skip_verify", "secure", "encrypted", "encryption"}
integrity_attrs := {"checksum", "hash", "sha256", "sha512", "md5", "integrity", "signature", "digest"}
auth_attrs := {"authentication", "auth_type", "verify"}
cert_validation_attrs := {"cert_validation", "insecure", "insecure_skip_verify"}

# Resource types commonly handling remote data or artifacts
artifact_types := {"source", "url", "uri", "blob", "object", "artifact", "package", "template", "file", "archive", "zip", "tar", "image"}
endpoint_types := {"endpoint", "api_endpoint", "base_url"}
connection_types := {"connection_string", "dsn", "host", "server"}

# Helper: Check if value indicates insecure/disabled state
is_insecure_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    lower_val == "false"
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    lower_val == "disabled"
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    lower_val == "off"
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    lower_val == "none"
} else {
    value.ir_type == "Integer"
    value.value == 0
}

# Helper: Check if value indicates insecure/enabled state (for skip_verify type attributes)
is_insecure_enabled(value) {
    value.ir_type == "Boolean"
    value.value == true
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    lower_val == "true"
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    lower_val == "enabled"
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    lower_val == "on"
}

# Helper: Check if protocol is insecure
has_insecure_protocol(value) {
    value.ir_type == "String"
    proto := lower(value.value)
    insecure_protocols[proto]
} else {
    value.ir_type == "String"
    regex.match("^http://", lower(value.value))
} else {
    value.ir_type == "String"
    regex.match("^(tcp|udp|plaintext)://", lower(value.value))
}

# Check if attribute name matches any in a set
attr_name_matches(name, name_set) {
    name_set[name]
} else {
    some n in name_set
    contains(lower(name), n)
}

# Find all attribute names recursively in a node (including nested structures)
find_attr_names(node, names) {
    node.ir_type == "Attribute"
    names := {node.name | true}
} else {
    node.ir_type == "Attribute"
    nested := find_all_attr_names_in_value(node.value)
    names := {node.name} | nested
} else {
    node.ir_type == "KeyValue"
    names := {node.name | true}
} else {
    node.ir_type == "Hash"
    names := find_all_attr_names_in_hash(node)
} else {
    names := set()
}

find_all_attr_names_in_hash(hash_node) = names {
    hash_node.ir_type == "Hash"
    names := {k |
        some k, v in hash_node.value
        k.ir_type == "String"
    } | {n |
        some k, v in hash_node.value
        nested := find_all_attr_names_in_value(v)
        some n in nested
    }
}

find_all_attr_names_in_value(val_node) = names {
    val_node.ir_type == "Attribute"
    names := find_attr_names(val_node, _)
} else {
    val_node.ir_type == "Hash"
    names := find_all_attr_names_in_hash(val_node)
} else {
    val_node.ir_type == "Array"
    names := {n |
        some item in val_node.value
        nested := find_all_attr_names_in_value(item)
        some n in nested
    }
} else {
    names := set()
}

# Collect all attribute names from atomic unit attributes
collect_atomic_unit_attr_names(attrs) = names {
    names := {n |
        some attr in attrs
        attr.ir_type == "Attribute"
        n := attr.name
    } | {n |
        some attr in attrs
        attr.ir_type == "Attribute"
        nested := find_all_attr_names_in_value(attr.value)
        some n in nested
    }
}

# Check for missing integrity-related attributes when they should be present
missing_integrity_check(node, all_attr_names) {
    # Check for artifact/source types without integrity verification
    (
        attr_name_matches(node.name, artifact_types)
        node.value.ir_type == "String"
        not has_integrity_attrs(all_attr_names)
    )
} else {
    # Check for endpoint without TLS/verification
    (
        attr_name_matches(node.name, endpoint_types)
        has_insecure_protocol(node.value)
        not has_tls_attrs(all_attr_names)
    )
}

# Check if integrity-related attributes exist
has_integrity_attrs(attr_names) {
    some attr in attr_names
    attr_name_matches(attr, integrity_attrs)
}

# Check if TLS/SSL verification attributes exist
has_tls_attrs(attr_names) {
    some attr in attr_names
    attr_name_matches(attr, ssl_tls_attrs)
}

# Check if authentication attributes exist
has_auth_attrs(attr_names) {
    some attr in attr_names
    attr_name_matches(attr, auth_attrs)
}

# Check if certificate validation attributes exist
has_cert_validation_attrs(attr_names) {
    some attr in attr_names
    attr_name_matches(attr, cert_validation_attrs)
}

# Main rule: Detect disabled/missing integrity checks
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for explicitly disabled security features
    (
        # SSL/TLS explicitly disabled
        (
            attr_name_matches(attr.name, ssl_tls_attrs)
            is_insecure_disabled(attr.value)
        )
        # Insecure skip verify enabled
        ; {
            contains(lower(attr.name), "insecure_skip_verify")
            is_insecure_enabled(attr.value)
        }
        # Cert validation disabled
        ; {
            attr_name_matches(attr.name, cert_validation_attrs)
            is_insecure_disabled(attr.value)
        }
        # Encryption explicitly disabled
        ; {
            attr_name_matches(attr.name, {"encrypted", "encryption"})
            is_insecure_disabled(attr.value)
        }
        # Authentication set to none/anonymous
        ; {
            attr_name_matches(attr.name, auth_attrs)
            attr.value.ir_type == "String"
            lower(attr.value.value) in {"none", "anonymous", "no", "disabled", "off"}
        }
    )

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Security verification mechanism is disabled or improperly configured. (CWE-353)"
    }
}

# Main rule: Detect insecure protocols without proper verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for insecure protocol usage in URL/endpoint/source attributes
    attr_name_matches(attr.name, artifact_types | endpoint_types | connection_types | {"protocol", "scheme", "transport"})
    has_insecure_protocol(attr.value)

    # Collect all attribute names to check for missing integrity mechanisms
    all_attr_names := collect_atomic_unit_attr_names(attrs)
    not has_integrity_attrs(all_attr_names)
    not has_tls_attrs(all_attr_names)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Insecure protocol used without integrity verification mechanism. (CWE-353)"
    }
}

# Main rule: Detect missing integrity verification on remote resources
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)

    # Check if this looks like a remote resource fetch
    some source_attr in attrs
    attr_name_matches(source_attr.name, {"source", "url", "uri", "src", "repository", "registry"})
    source_attr.value.ir_type == "String"

    # Collect all attribute names
    all_attr_names := collect_atomic_unit_attr_names(attrs)

    # Check for missing integrity verification
    not has_integrity_attrs(all_attr_names)

    # Additional check: also no GPG/checksum verification
    not has_gpg_check(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": source_attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Remote resource fetched without integrity verification. (CWE-353)"
    }
}

# Helper: Check for GPG/checksum verification attributes
has_gpg_check(attrs) {
    some attr in attrs
    attr.ir_type == "Attribute"
    contains(lower(attr.name), "gpg")
    not is_insecure_disabled(attr.value)
} else {
    some attr in attrs
    attr.ir_type == "Attribute"
    contains(lower(attr.name), "check")
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

