package glitch

import data.glitch_lib

insecure_protocols := {"http", "ftp", "telnet"}

integrity_keywords := {"checksum", "hash", "sha256", "sha512", "md5", "gpg", "signature", "signature_", "_signature", "integrity", "digest", "verify", "verify_enable", "_verify", "verify_", "verified", "fingerprint", "sign", "signed", "asc", "detached"}

ssl_tls_keywords := {"ssl", "tls", "_ssl", "_tls", "ssl_", "tls_", "verify_ssl", "verify_tls", "use_ssl", "force_ssl", "require_ssl", "ssl_mode", "ssl_verify", "certificate", "cert", "validate_certs", "validate_certificate"}

insecure_value_patterns := ["^(?i)(false|no|off|disable|disabled|none|0|skip|ignore)$", "^(?i)(true)$"]

is_false_value(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    regex.match(insecure_value_patterns[0], value.value)
} else {
    value.ir_type == "Integer"
    value.value == 0
}

is_true_value(value) {
    value.ir_type == "Boolean"
    value.value == true
} else {
    value.ir_type == "String"
    regex.match(insecure_value_patterns[1], value.value)
}

has_insecure_protocol(value) {
    value.ir_type == "String"
    regex.match("^(?i)http://", value.value)
} else {
    value.ir_type == "String"
    regex.match("^(?i)(ftp|telnet)://", value.value)
}

attr_name_contains(target, keyword) {
    lower(target) == lower(keyword)
} else {
    contains(lower(target), sprintf("%s_", [lower(keyword)]))
} else {
    contains(lower(target), sprintf("_%s", [lower(keyword)]))
}

has_integrity_related_attr(attrs) {
    attr := attrs[_]
    kw := integrity_keywords[_]
    attr_name_contains(attr.name, kw)
    not is_false_value(attr.value)
}

has_ssl_tls_attr(attrs) {
    attr := attrs[_]
    kw := ssl_tls_keywords[_]
    attr_name_contains(attr.name, kw)
    not is_false_value(attr.value)
}

is_gpgcheck_disabled(attr) {
    attr_name_contains(attr.name, "gpgcheck")
    is_false_value(attr.value)
}

is_verify_disabled(attr) {
    attr_name_contains(attr.name, "verify")
    is_false_value(attr.value)
}

is_insecure_enabled_attr(attr) {
    attr_name_contains(attr.name, "insecure")
    is_true_value(attr.value)
}

is_insecure_protocol_with_no_integrity(attrs, attr) {
    has_insecure_protocol(attr.value)
    not has_integrity_related_attr(attrs)
}

collect_all_hash_keys(node) = keys {
    keys := {k |
        walk(node, [_, n])
        n.ir_type == "Hash"
        [_, pair] := walk(n.value)
        pair.key.ir_type == "String"
        k := pair.key.value
    }
}

check_hash_for_disabled_integrity(hash_node) {
    [_, pair] := walk(hash_node.value)
    pair.key.ir_type == "String"
    attr_name_contains(pair.key.value, "gpgcheck")
    pair.value.ir_type == "Integer"
    pair.value.value == 0
}

