insecure_protocols := {"http://", "ftp://", "telnet://"}

# Keywords indicating integrity verification
integrity_keywords := {"checksum", "hash", "sha256", "sha512", "sha1", "md5", "gpg", "gpgcheck", "repo_gpgcheck", "pkg_gpgcheck", "signature", "s3_url_signed", "sign", "signed", "digest", "verify", "verification", "fingerprint", "asc", "detached"}

# SSL/TLS related keywords
ssl_tls_keywords := {"ssl", "tls", "verify_ssl", "verify_tls", "use_ssl", "force_ssl", "require_ssl", "ssl_mode", "ssl_verify", "certificate", "cert", "validate_certs", "validate_certificate", "verify_peer", "verify_mode"}

# Patterns indicating disabled/insecure values
disabled_patterns := ["(?i)^(false|no|off|disable|disabled|none|0|skip|ignore)$"]
enabled_patterns := ["(?i)^(true|yes|on|enable|enabled|1)$"]

# Check if value represents disabled/false state
is_disabled_value(value) {
    value.ir_type == "Boolean"
    not value.value
} else {
    value.ir_type == "String"
    regex.match(disabled_patterns[0], value.value)
} else {
    value.ir_type == "Integer"
    value.value == 0
}

# Check if value represents enabled/true state
is_enabled_value(value) {
    value.ir_type == "Boolean"
    value.value
} else {
    value.ir_type == "String"
    regex.match(enabled_patterns[0], value.value)
}

# Check if string starts with insecure protocol
is_insecure_url(value) {
    value.ir_type == "String"
    proto := insecure_protocols[_]
    startswith(lower(value.value), proto)
}

# Check if attribute name contains keyword (case-insensitive, with underscore variations)
name_matches_keyword(name, keyword) {
    lower(name) == lower(keyword)
} else {
    contains(lower(name), sprintf("%s_", [lower(keyword)]))
} else {
    contains(lower(name), sprintf("_%s", [lower(keyword)]))
} else {
    contains(lower(name), lower(keyword))
}

# Check if any attribute has an integrity-related keyword in its name with a non-disabled value
has_integrity_verification(attrs) {
    attr := attrs[_]
    kw := integrity_keywords[_]
    name_matches_keyword(attr.name, kw)
    not is_disabled_value(attr.value)
}

# Check if any attribute has SSL/TLS verification enabled
has_ssl_verification(attrs) {
    attr := attrs[_]
    kw := ssl_tls_keywords[_]
    name_matches_keyword(attr.name, kw)
    not is_disabled_value(attr.value)
}

# Recursive check for disabled gpgcheck in Hash structures
has_disabled_gpgcheck_in_hash(node) {
    walk(node, [_, n])
    n.ir_type == "Hash"
    [_, pair] := walk(n.value)
    pair.key.ir_type == "String"
    name_matches_keyword(pair.key.value, "gpgcheck")
    is_disabled_value(pair.value)
}

# Check for source/url attribute with insecure protocol and no integrity verification
check_insecure_source_no_integrity(node, attrs) {
    attr := attrs[_]
    name_matches_keyword(attr.name, "source")
    is_insecure_url(attr.value)
    not has_integrity_verification(attrs)
}

check_insecure_source_no_integrity(node, attrs) {
    attr := attrs[_]
    name_matches_keyword(attr.name, "url")
    is_insecure_url(attr.value)
    not has_integrity_verification(attrs)
}

check_insecure_source_no_integrity(node, attrs) {
    attr := attrs[_]
    name_matches_keyword(attr.name, "uri")
    is_insecure_url(attr.value)
    not has_integrity_verification(attrs)
}

# Check for remote_file with http and no checksum
check_remote_file_insecure(node, attrs) {
    name_matches_keyword(node.type, "remote_file")
    attr := attrs[_]
    name_matches_keyword(attr.name, "source")
    is_insecure_url(attr.value)
    not has_integrity_verification(attrs)
}

# Rule: Disabled certificate/SSL/TLS validation
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    kw := ssl_tls_keywords[_]
    name_matches_keyword(attr.name, kw)
    is_disabled_value(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - SSL/TLS validation is disabled. (CWE-353)"
    }
}

# Rule: Disabled GPG/signature check in attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    name_matches_keyword(attr.name, "gpgcheck")
    is_disabled_value(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - GPG signature verification is disabled. (CWE-353)"
    }
}

# Rule: Disabled integrity/checksum verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    kw := integrity_keywords[_]
    name_matches_keyword(attr.name, kw)
    is_disabled_value(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Integrity verification mechanism is disabled. (CWE-353)"
    }
}

# Rule: Insecure skip verify enabled
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    name_matches_keyword(attr.name, "insecure")
    is_enabled_value(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Insecure mode is explicitly enabled. (CWE-353)"
    }
}

# Rule: Insecure protocol with source/url and no integrity check
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)

    check_insecure_source_no_integrity(node, attrs)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - Insecure protocol used without integrity verification. (CWE-353)"
    }
}

# Rule: Disabled GPG check in variable hash structures (e.g., repository configurations)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    has_disabled_gpgcheck_in_hash(var.value)

    result := {
        "type": "sec_no_int_check",
        "element": var,
        "path": parent.path,
        "description": "Missing support for integrity check - GPG signature check disabled in configuration. (CWE-353)"
    }
}

# Rule: remote_file with http source and no checksum/integrity verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)

    check_remote_file_insecure(node, attrs)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - Remote file retrieved over insecure protocol without integrity verification. (CWE-353)"
    }
}

package glitch

import data.glitch_lib

# Insecure protocols that lack integrity protection
insecure_protocols := {"http://", "ftp://", "telnet://"}

# Check if value represents disabled/false state
is_disabled_value(value) {
    value.ir_type == "Boolean"
    not value.value
} else {
    value.ir_type == "String"
    regex.match("^(?i:false|no|off|disable|disabled|none|0|skip|ignore|untrusted)$", value.value)
} else {
    value.ir_type == "Integer"
    value.value == 0
}

# Check if string starts with insecure protocol (case insensitive)
is_insecure_url(value) {
    value.ir_type == "String"
    l_val := lower(value.value)
    proto := insecure_protocols[_]
    startswith(l_val, proto)
}

# Check for disabled SSL/TLS validation in attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    regex.match("(?i)^(validate_?certs|verify_?(ssl|tls|cert|peer)|insecure_?skip_?verify|ssl_?verify|cert_?validation|tls_?verify|skip_?verify)$", attr.name)
    is_disabled_value(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - SSL/TLS certificate validation is disabled. (CWE-353)"
    }
}

# Check for disabled GPG/signature verification in attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    regex.match("(?i)^(gpgcheck|repo_?gpgcheck|pkg_?gpgcheck|enable_?gpg|sign(ature)?_?check|verify_?sign(ature)?)$", attr.name)
    is_disabled_value(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - GPG/signature verification is disabled. (CWE-353)"
    }
}

# Find disabled gpgcheck in hash structures breadth-first
find_disabled_gpgcheck_hash(node) {
    node.ir_type == "Hash"
    kv := node.value[_]
    kv.key.ir_type == "String"
    regex.match("(?i)^gpgcheck$", kv.key.value)
    is_disabled_value(kv.value)
}

find_disabled_gpgcheck_in_children(node) {
    node.ir_type == "Hash"
    kv := node.value[_]
    find_disabled_gpgcheck_nested(kv.value)
}

find_disabled_gpgcheck_in_children(node) {
    node.ir_type == "Array"
    elem := node.value[_]
    find_disabled_gpgcheck_nested(elem)
}

# Non-recursive helper that delegates to find_disabled_gpgcheck_hash or traverses deeper
find_disabled_gpgcheck_nested(node) {
    find_disabled_gpgcheck_hash(node)
} else {
    find_disabled_gpgcheck_in_children(node)
}

# Check for disabled GPG check in nested variable hash structures
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    find_disabled_gpgcheck_nested(var.value)

    result := {
        "type": "sec_no_int_check",
        "element": var,
        "path": parent.path,
        "description": "Missing support for integrity check - GPG signature check disabled in configuration. (CWE-353)"
    }
}

# Helper to check if any integrity-related attribute exists
has_integrity_attribute(attrs) {
    attr := attrs[_]
    regex.match("(?i)^(checksum|hash|md5|sha(1|256|512|384)|digest|signature|gpg|verify|hmac|crc)$", attr.name)
}

# Check for remote file/URL downloads with insecure protocols and no integrity check
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    regex.match("(?i)^(remote_?file|get_?url|uri|download|fetch|artifact|package)$", node.type)

    attrs := glitch_lib.all_attributes(node)

    attr := attrs[_]
    regex.match("(?i)^(source|url|uri|location|href|src)$", attr.name)
    is_insecure_url(attr.value)

    not has_integrity_attribute(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - Insecure protocol used without integrity verification. (CWE-353)"
    }
}

# Check for insecure protocol in any source-like attribute within remote resources
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    regex.match("(?i)(remote|url|http|download|fetch|get|source|archive|tar|zip)", node.type)

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    regex.match("(?i)^(source|url|uri|location|href|src|origin|repository|registry)$", attr.name)
    is_insecure_url(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Insecure protocol used for remote resource. (CWE-353)"
    }
}
